import { isWon } from '../game.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { StatusLabel } from './status-labels.ts';
import type { GameState } from '../game.ts';
import './status.css';

interface GameStatusProps {
  game: GameState;
  best: number | undefined;
  celebration: boolean;
}

export function GameStatus({ game, best, celebration }: GameStatusProps) {
  return (
    <>
      <dl className="stats">
        <div>
          <dt>{StatusLabel.moves}</dt> <dd>{game.moves}</dd>
        </div>
        <div>
          <dt>{StatusLabel.pairs}</dt>{' '}
          <dd>
            {game.matched.length / 2}/{game.deck.length / 2}
          </dd>
        </div>
        <div>
          <dt>{StatusLabel.time}</dt> <dd>{formatElapsed(game.elapsedMs)}</dd>
        </div>
        <div>
          <dt>{StatusLabel.best}</dt> <dd>{best ?? 0}</dd>
        </div>
      </dl>
      {isWon(game) && (
        <p className={`victory${celebration ? ' celebrate' : ''}`}>
          Every pair found in {game.moves} moves and {formatElapsed(game.elapsedMs)}. Well played.
        </p>
      )}
    </>
  );
}
export const StatusLabel = {
  moves: 'Moves:',
  pairs: 'Pairs:',
  time: 'Time:',
  best: 'Best:',
} as const;
import { activateCard, advanceGame, createGame, isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { rememberBest } from './storage.ts';
import type { GameState } from '../game.ts';
import type { Preferences } from './storage.ts';

export interface Session {
  readonly game: GameState;
  readonly paused: boolean;
  readonly generation: number;
  readonly feedback: string;
  readonly loadNotice: string;
  readonly announcement: number;
  readonly celebration: boolean;
  readonly preferences: Preferences;
}

export const SessionNotice = {
  loaded: 'Loaded snapshot. Select Resume to continue.',
  loadedCompleted: 'Loaded completed snapshot.',
  invalidBoard: 'Invalid board code.',
  invalidSnapshot: 'Invalid snapshot.',
} as const;

export function initialSession(code: string, preferences: Preferences): Session {
  return {
    game: createGame(code),
    paused: false,
    generation: 0,
    feedback: '',
    loadNotice: '',
    announcement: 0,
    celebration: false,
    preferences,
  };
}

export function replaceGame(session: Session, game: GameState, imported: boolean): Session {
  const paused = imported && !isWon(game);
  const loadNotice = imported
    ? paused
      ? SessionNotice.loaded
      : SessionNotice.loadedCompleted
    : '';
  return {
    ...session,
    game,
    paused,
    generation: session.generation + 1,
    celebration: false,
    preferences: { ...session.preferences, size: game.size },
    // Only loads have a published status. A new deal clears the last turn result silently.
    announcement: imported ? session.announcement + 1 : session.announcement,
    feedback: loadNotice,
    loadNotice,
  };
}

export function tickSession(session: Session, generation: number, milliseconds: number): Session {
  if (session.generation !== generation || session.paused) return session;
  const game = advanceGame(session.game, milliseconds);
  return game === session.game ? session : { ...session, game };
}

export function activateSession(session: Session, index: number): Session {
  if (session.paused) return session;
  const game = activateCard(session.game, index);
  if (game === session.game) return session;
  if (game.selection.kind === SelectionKind.one) return { ...session, game };
  const won = isWon(game);
  const feedback = won
    ? `Pair found. All pairs found in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}.`
    : game.selection.kind === SelectionKind.mismatch
      ? 'No match. Cards close after a short pause.'
      : `Pair found. ${game.matched.length / 2} ${game.matched.length === 2 ? 'pair' : 'pairs'} matched.`;
  const preferences = won
    ? rememberBest(session.preferences, game.size, game.moves)
    : session.preferences;
  return {
    ...session,
    game,
    feedback,
    announcement: session.announcement + 1,
    preferences,
    celebration: won,
  };
}

import assert from 'node:assert/strict';
import { test } from 'vitest';
import {
  DEFAULT_SIZE,
  PREFERENCES_KEY,
  PREFERENCES_VERSION,
  readPreferences,
  rememberBest,
  writePreferences,
} from './storage.ts';
import { MOVES_MAX } from '../game.ts';
import { SPEC_VECTOR } from '../game.fixture.ts';
import type { PreferenceStore } from './storage.ts';

function memoryStore(initial = ''): PreferenceStore {
  const entries = new Map([[PREFERENCES_KEY, initial]]);
  return {
    getItem: (key) => entries.get(key) ?? null,
    setItem: (key, value) => {
      entries.set(key, value);
    },
  };
}

test('preferences round trip size and separate minimum moves per size', () => {
  const store = memoryStore();
  const preferences = rememberBest(rememberBest({ size: 6, bestMoves: {} }, 4, 12), 6, 20);
  writePreferences(store, preferences);
  assert.deepEqual(readPreferences(store), preferences, 'R10 scores survive storage round trip');
  assert.equal(rememberBest(preferences, 4, 13), preferences, 'R10 worse score keeps best');
  assert.equal(rememberBest(preferences, 4, 12), preferences);
  assert.equal(rememberBest(preferences, 4, 9).bestMoves['4'], 9, 'R10 better score replaces best');
  assert.equal(preferences.bestMoves['6'], 20, 'R10 size six has its separate best');
});

test('a best at the move cap round trips and a larger saved best is ignored', () => {
  const store = memoryStore();
  const capped = { size: DEFAULT_SIZE, bestMoves: { [DEFAULT_SIZE]: MOVES_MAX } };
  writePreferences(store, capped);
  assert.deepEqual(readPreferences(store), capped);
  assert.equal(rememberBest(capped, DEFAULT_SIZE, MOVES_MAX), capped);
  const larger = {
    schemaVersion: PREFERENCES_VERSION,
    size: DEFAULT_SIZE,
    bestMoves: { [DEFAULT_SIZE]: MOVES_MAX + 1 },
  };
  store.setItem(PREFERENCES_KEY, JSON.stringify(larger));
  assert.deepEqual(readPreferences(store), { size: DEFAULT_SIZE, bestMoves: {} });
});

const INVALID_PREFERENCES = [
  '{',
  'null',
  '{}',
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 5, bestMoves: {} }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: -1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 8.5 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { '04': 8 } }),
];
for (const [index, text] of INVALID_PREFERENCES.entries()) {
  test(`preferences ignore invalid saved data ${index + 1}`, () => {
    assert.deepEqual(readPreferences(memoryStore(text)), { size: DEFAULT_SIZE, bestMoves: {} });
  });
}

test('storage failures keep play available and never change unrelated keys', () => {
  const denied: PreferenceStore = {
    getItem: () => {
      throw new Error();
    },
    setItem: () => {
      throw new Error();
    },
  };
  assert.equal(DEFAULT_SIZE, SPEC_VECTOR.sizes[0]);
  assert.equal(readPreferences(denied).size, DEFAULT_SIZE);
  assert.doesNotThrow(() => writePreferences(denied, { size: DEFAULT_SIZE, bestMoves: {} }));
  assert.equal(readPreferences(null).size, DEFAULT_SIZE);
  const store = memoryStore();
  const unrelated = 'another-application';
  store.setItem(unrelated, 'kept');
  writePreferences(store, { size: DEFAULT_SIZE, bestMoves: {} });
  assert.equal(store.getItem(unrelated), 'kept');
});
import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { ReproductionControl } from '../src/game/controls/control-labels.ts';
import { DEFAULT_SIZE, PREFERENCES_KEY, PREFERENCES_VERSION } from '../src/game/session/storage.ts';
import { SelectionKind } from '../src/game/selection.ts';
import { SNAPSHOT_VERSION } from '../src/game/snapshot.ts';
import { StatusLabel } from '../src/game/status/status-labels.ts';
import type { Page } from '@playwright/test';

const PERFECT = EXAMPLE_PAIRS.length;

function shownBest(page: Page) {
  return page
    .locator('.stats > div')
    .filter({ has: page.getByText(StatusLabel.best, { exact: true }) })
    .locator('dd');
}

// Stores a best as an earlier visit would have saved it.
async function saveBest(page: Page, moves: number): Promise<void> {
  const saved = JSON.stringify({
    schemaVersion: PREFERENCES_VERSION,
    size: DEFAULT_SIZE,
    bestMoves: { [DEFAULT_SIZE]: moves },
  });
  await page.evaluate(([key, value]) => localStorage.setItem(key, value), [
    PREFERENCES_KEY,
    saved,
  ] as const);
}

function savedBest(page: Page) {
  return page.evaluate((key) => localStorage.getItem(key), PREFERENCES_KEY);
}

// A worse completed import is the case only a browser can show: the saved best and its label stay as they were.
for (const [saved, imported] of [[PERFECT, PERFECT + 2]] as const)
  test(`a completed import in ${imported} moves leaves a saved best of ${saved} alone`, async ({
    page,
    gameURL,
  }) => {
    await page.goto(gameURL);
    await saveBest(page, saved);
    await page.reload();
    const best = shownBest(page);
    await expect(best).toHaveText(String(saved));
    const before = await savedBest(page);
    await best.evaluate((element) => {
      const changes: string[] = [];
      element.setAttribute('data-changes', '[]');
      new MutationObserver(() => {
        changes.push(element.textContent ?? '');
        element.setAttribute('data-changes', JSON.stringify(changes));
      }).observe(element, { childList: true, characterData: true, subtree: true });
    });
    const completed = {
      version: SNAPSHOT_VERSION,
      boardCode: EXAMPLE_CODE,
      matched: EXAMPLE_PAIRS.flat(),
      selection: { kind: SelectionKind.closed },
      moves: imported,
      elapsedMs: 0,
      started: true,
    };
    await page.locator('summary').click();
    await page
      .getByLabel(ReproductionControl.snapshot, { exact: true })
      .fill(JSON.stringify(completed));
    await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
    await expect(page.locator('.card.matched')).toHaveCount(PERFECT * 2);
    const changes: unknown = JSON.parse((await best.getAttribute('data-changes')) ?? '[]');
    expect(changes, 'C12 import leaves the shown best alone').toEqual([]);
    expect(await savedBest(page), 'C12 import leaves the saved best alone').toBe(before);
  });

import { GRID_SIZES, isValidSize } from '../deck.ts';
import { MOVES_MAX } from '../game.ts';
import { isJsonObject, isNonnegativeSafeInteger, parseJson } from '../saved-format.ts';

export const DEFAULT_SIZE = GRID_SIZES[0];
export const PREFERENCES_KEY = 'neon-pairs.preferences.v1';
export const PREFERENCES_VERSION = 1;
export interface Preferences {
  readonly size: number;
  readonly bestMoves: Readonly<Record<string, number>>;
}
export interface PreferenceStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export function readPreferences(store: PreferenceStore | null): Preferences {
  const fallback: Preferences = { size: DEFAULT_SIZE, bestMoves: {} };
  try {
    const text = store?.getItem(PREFERENCES_KEY);
    if (!text) return fallback;
    const value = parseJson(text);
    if (
      !isJsonObject(value) ||
      value.schemaVersion !== PREFERENCES_VERSION ||
      typeof value.size !== 'number'
    )
      return fallback;
    if (!isValidSize(value.size) || !isJsonObject(value.bestMoves)) return fallback;
    const bestMoves: Record<string, number> = {};
    for (const [size, moves] of Object.entries(value.bestMoves)) {
      const numberSize = Number(size);
      if (
        String(numberSize) !== size ||
        !isValidSize(numberSize) ||
        !isNonnegativeSafeInteger(moves) ||
        moves > MOVES_MAX ||
        moves < numberSize ** 2 / 2
      )
        return fallback;
      bestMoves[size] = moves;
    }
    return { size: value.size, bestMoves };
  } catch {
    return fallback;
  }
}

export function writePreferences(store: PreferenceStore | null, preferences: Preferences): void {
  try {
    store?.setItem(
      PREFERENCES_KEY,
      JSON.stringify({ schemaVersion: PREFERENCES_VERSION, ...preferences }),
    );
  } catch {
    // A blocked browser store doesn't stop the current game.
  }
}

export function rememberBest(preferences: Preferences, size: number, moves: number): Preferences {
  return { ...preferences, bestMoves: { ...preferences.bestMoves, [size]: moves } };
}
import { useEffect } from 'react';
import { writePreferences } from './storage.ts';
import type { Preferences, PreferenceStore } from './storage.ts';

// Reading localStorage can throw when the browser blocks storage, and play continues without it.
export function browserStore(): PreferenceStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

// Saves this tab's size and bests after each change.
export function useSavedPreferences(store: PreferenceStore | null, preferences: Preferences) {
  useEffect(() => {
    writePreferences(store, preferences);
  }, [preferences, store]);
}

